def gen(rng):
    import math

    def val(alpha, p, q):
        sp, sq = sum(p), sum(q)
        total = 0.0
        for x, y in zip(p, q):
            total += (x / sp) ** alpha / (y / sq) ** (alpha - 1)
        return math.log(total) / (alpha - 1) * 1000

    def ok(alpha, p, q):
        v = val(alpha, p, q)
        return v >= 1.0 and abs(v - math.floor(v) - 0.5) > 1e-4

    alphas = ['0.01', '0.1', '0.25', '0.5', '0.75', '1.5', '2', '2.5', '3', '4', '5', '7.5', '8', '1.01', '0.99']

    def fmt(a, p, q):
        return f"{len(p)} {a}\n" + " ".join(map(str, p)) + "\n" + " ".join(map(str, q))

    tests = []
    fixed = [
        ('2', [1, 1, 2], [2, 1, 1]), ('0.5', [1, 3], [1, 1]), ('3', [1, 1], [1, 3]),
        ('2', [1], [1000000]), ('8', [1000000, 1], [1, 1000000]), ('0.01', [5, 1, 9], [2, 2, 2]),
    ]
    for a, p, q in fixed:
        if len(p) == 1:
            tests.append(fmt(a, p, q))
        elif ok(float(a), p, q):
            tests.append(fmt(a, p, q))
    while len(tests) < 60:
        n = rng.randint(1, 6)
        m = rng.choice([3, 9, 50])
        a = rng.choice(alphas)
        p = [rng.randint(1, m) for _ in range(n)]
        q = [rng.randint(1, m) for _ in range(n)]
        if n == 1 or ok(float(a), p, q):
            tests.append(fmt(a, p, q))
    N = 10 ** 5
    made = 0
    while made < 6:
        a = rng.choice(['0.5', '2', '3', '8', '0.01', '1.5'])
        mode = made % 3
        if mode == 0:
            p = [rng.randint(1, 10 ** 6) for _ in range(N)]
            q = [rng.randint(1, 10 ** 6) for _ in range(N)]
        elif mode == 1:
            p = [rng.randint(1, 100) for _ in range(N)]
            q = [rng.randint(90, 110) for _ in range(N)]
        else:
            p = [rng.randint(1, 10 ** 6) for _ in range(N)]
            q = [max(1, x + rng.randint(-(x // 2), x // 2)) for x in p]
        if ok(float(a), p, q):
            tests.append(fmt(a, p, q))
            made += 1
    return tests
